import { ClickableTile } from '@carbon/react'
import PropTypes from 'prop-types'
import React, { useCallback } from 'react'

const VALID_KEYS = ['click', ' ', 'Enter']

export const IdeCard = ({
  cardId,
  onInteract,
  cardHref,
  cardHeading,
  cardHeadingDescription,
  cardGraphic
}) => {
  // triggers a callback if event key matches one in VALID_KEYS
  const keyAndClickHandler = useCallback(evt => {
    if (evt && (evt.type || evt.key) && (
      VALID_KEYS.includes(evt.type) ||
      VALID_KEYS.includes(evt.key)
    )) {
      if (!cardHref) {
        evt.preventDefault()
      }
      if (onInteract) {
        onInteract(cardId)
      }
    }
  }, [cardHref, cardId, onInteract])

  return (
    <ClickableTile
      tabIndex={0}
      className='ide-card--card-overrides'
      href={cardHref || '#'} // add an href which does nothing so a click can be registered
      target={undefined}
      onKeyPress={keyAndClickHandler}
      onClick={keyAndClickHandler}
    >
      <div className='ide-card--top'>
        <div className='ide-card--tile-img'>
          {cardGraphic}
        </div>
        <p className='ide-card--heading'>
          {cardHeading}
        </p>
      </div>
      <div className='ide-card--heading-description'>
        {cardHeadingDescription}
      </div>
    </ClickableTile>
  )
}

IdeCard.propTypes = {
  /** Required property - icon to be displayed on the card */
  cardGraphic: PropTypes.object.isRequired,
  /** Required property - card main text */
  cardHeading: PropTypes.string.isRequired,
  /** Optional prop - small text displayed at the bottom of the card */
  cardHeadingDescription: PropTypes.string,
  /** Optional property - Link to be used for the underlying anchor */
  cardHref: PropTypes.string,
  /** The unique id of the card */
  cardId: PropTypes.string,
  /** OnClick handler - callback function to model the onClick behaviour of a card */
  onInteract: PropTypes.func
}
