import { Tag } from '@carbon/react'
import { Close, Search } from '@carbon/react/icons/index.js'
import classnames from 'classnames'
import pluralize from 'pluralize'
import PropTypes from 'prop-types'
import React, { Fragment } from 'react'
// eslint-disable-next-line import/extensions
import CreatableSelect from 'react-select/creatable'

const Highlight = React.memo(({ children, search }) => {
  if (
    // We accept arbitrary React nodes but we can't highlight them
    typeof children !== 'string' ||
    !search
  ) {
    return children
  }

  const searchRegExp = new RegExp(
    search.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'),
    'ig'
  )
  const newChildren = []
  let result
  let index = 0

  while ((result = searchRegExp.exec(children)) !== null) {
    newChildren.push(
      // Non-matching substring (could be empty)
      children.substring(index, result.index),

      // Matching substring (can't be empty)
      <mark key={newChildren.length}>
        {children.substring(result.index, searchRegExp.lastIndex)}
      </mark>
    )

    index = searchRegExp.lastIndex
  }

  // Remainder of string did not match (could be empty)
  newChildren.push(children.substring(index))

  return newChildren
})

Highlight.displayName = 'Highlight'

Highlight.propTypes = {
  children: PropTypes.oneOfType([PropTypes.string, PropTypes.node]),
  search: PropTypes.string
}

// custom styling
const customStyles = {
  multiValueLabel: provided => ({
    ...provided,
    color: 'inherit'
  }),
  control: (provided, state) => {
    let style = {
      ...provided,
      borderRadius: 0,
      paddingLeft: '26px',
      minHeight: '3rem',
      outline: '2px solid transparent',
      // important overrides
      borderTop: 'none',
      borderRight: 'none',
      borderLeft: 'none',
      backgroundColor: undefined
    }
    if (state.isFocused || state.isHovered) {
      style = {
        ...style,
        borderBottom: 'solid 1px transparent',
        paddingLeft: '27px'
      }
    }
    return style
  },
  menu: provided => ({
    ...provided,
    borderRadius: 0,
    padding: '1rem 26px',
    margin: '2px 0',
    // important overrides
    backgroundColor: undefined
  }),
  placeholder: provided => ({
    ...provided
  }),
  groupHeading: provided => ({
    ...provided,
    textTransform: 'none',
    fontSize: '0.875rem'
  })
}

// custom behaviour
const getNewOptionData = (inputValue, optionLabel) => ({
  label: optionLabel,
  value: inputValue,
  __plaintext__: true
})

const formatCreateLabel = inputValue =>
  `Search for "${inputValue}"`

const findCategoryForOption = (option, allOptions) => {
  const category = allOptions.find(category =>
    category.options.find(thisOption => thisOption.value === option.value)
  )
  return pluralize.singular(category.label)
}

const formatOptionLabel = (option, context, allOptions) => {
  // highlight search text if we"re rendering an existing option in the menu,
  // not in the tags already selected, and not in the "seach for..." option
  const shouldHighlight = !context.selectValue.includes(option) && !option.__plaintext__
  // when rendering in the input, rather than the list, we want to include
  // the category name, but not for plain text searches
  const includeCategory = context.selectValue.includes(option) && !option.__plaintext__
  const valueSection = shouldHighlight
    ? (
      <Highlight search={context.inputValue}>{option.label}</Highlight>
      )
    : option.label

  return includeCategory
    ? (
      <>
        <span className='ide-filter--category'>
          {findCategoryForOption(option, allOptions)}:
        </span>
        {valueSection}
      </>
      )
    : valueSection
}

// custom components
const MultiValueContainer = ({ data, children }) => (
  <Tag
    type={data.type || 'filter'}
    className='ide-filter--tag'
  >
    <div className='ide-filter--tag-container'>
      {children}
    </div>
  </Tag>
)

MultiValueContainer.propTypes = {
  children: PropTypes.node,
  data: PropTypes.shape({
    type: PropTypes.string
  })
}

const MultiValueRemove = ({ data, innerProps }) => {
  const type = data.type || 'filter'
  return (
    <button
      type='button'
      {...innerProps}
      className={classnames({
        'ide-filter--close': true,
        'ide-filter--tag-filter': type === 'filter'
      })}
    >
      <Close size={16} description='Close' />
    </button>
  )
}

MultiValueRemove.propTypes = {
  data: PropTypes.shape({
    type: PropTypes.string
  }),
  innerProps: PropTypes.object
}

const DropdownIndicator = () => null

const IndicatorSeparator = () => null

const ClearIndicator = ({ innerProps }) => (
  <div {...innerProps} className='ide-filter--clear'>
    <Close size={16} description='Clear' />
  </div>
)

ClearIndicator.propTypes = {
  innerProps: PropTypes.object
}

export const IdeFilter = ({
  onChange,
  options
}) => (
  <div className='ide-filter'>
    <Search
      size={16}
      className='ide-filter--search-icon'
      description='What are you looking for today?'
    />
    <CreatableSelect
      components={{
        MultiValueContainer,
        MultiValueRemove,
        DropdownIndicator,
        IndicatorSeparator,
        ClearIndicator
      }}
      aria-label='Search'
      styles={customStyles}
      menuIsOpen={undefined}
      isMulti
      value={undefined}
      inputValue={undefined}
      onChange={onChange}
      onInputChange={undefined}
      onBlur={undefined}
      onFocus={undefined}
      options={options}
      placeholder='What are you looking for today?'
      className='ide-filter--select'
      classNamePrefix='ide-filter'
      formatOptionLabel={(option, context) =>
        formatOptionLabel(option, context, options)}
      formatCreateLabel={formatCreateLabel}
      getNewOptionData={getNewOptionData}
      loadingMessage={undefined}
      allowCreateWhileLoading
      isLoading={false}
      autoFocus={false}
    />
  </div>
)

IdeFilter.displayName = 'IdeFilter'

IdeFilter.propTypes = {
  onChange: PropTypes.func.isRequired,
  options: PropTypes.arrayOf(
    PropTypes.shape({
      label: PropTypes.string.isRequired,
      options: PropTypes.arrayOf(
        PropTypes.shape({
          label: PropTypes.string.isRequired,
          value: PropTypes.string.isRequired,
          type: PropTypes.string
        })
      ).isRequired
    })
  ).isRequired
}
