import PropTypes from 'prop-types'
import React from 'react'

export const IdePage = ({ heading, children }) => (
  <>
    {heading && (
      <section className='ide-page-header'>
        {heading}
      </section>
    )}
    <div className='ide-page-content'>
      {children}
    </div>
  </>
)

IdePage.propTypes = {
  heading: PropTypes.node,
  children: PropTypes.node.isRequired
}
